import { MOCK_DISPUTES } from "@/data/mock/disputes";
import { CaseFileLayout } from "@/components/disputes/CaseFileLayout";
import { notFound } from "next/navigation";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";

export function generateStaticParams() {
  return MOCK_DISPUTES.map((dispute) => ({
    id: dispute.id,
  }));
}

export default async function DisputePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const dispute = MOCK_DISPUTES.find((d) => d.id === id);

  if (!dispute) {
    notFound();
  }

  return (
    <div className="space-y-4 h-full">
      <div className="flex items-center gap-4">
        <Link href="/dashboard/disputes">
            <Button variant="ghost" size="sm">
                <ArrowLeft className="mr-2 h-4 w-4" /> Back to Disputes
            </Button>
        </Link>
      </div>
      <CaseFileLayout dispute={dispute} />
    </div>
  );
}
